mapper.select:
SELECT

FROM recipe r
JOIN category c ON r.category_id = c.id
JOIN `user` u ON r.user_id = u.id

    AND r.status = #{q.status}
    AND r.category_id = #{q.categoryId}
    AND r.user_id = #{q.userId}

        AND r.title LIKE CONCAT('%', #{q.keyword}, '%')


ORDER BY r.id DESC

mapper.update:
UPDATE recipe
SET views = views + 1
WHERE id = #{id}

UPDATE recipe
SET status        = #{status},
    reject_reason = #{reason}
WHERE id = #{id}
